package com.thang.user.controller;
import com.thang.user.repository.*;import com.thang.user.model.entity.AdminAccountAudit;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.PageRequest;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.LocalDateTime;import java.util.*;
@RestController @RequestMapping("/api/users/admin/operations") @PreAuthorize("hasRole('ADMIN')") @RequiredArgsConstructor
public class AuthOperationsController {
 private final AuthActivationOutboxRepository outbox;private final AdminAccountAuditRepository audit;
 public record Job(String id,String userId,int attempts,long nextAttempt,long expiresAt,boolean leased){}public record Retry(@NotBlank @Size(min=10,max=500) String reason){}
 @GetMapping public Map<String,Object> health(){return Map.of("service","user-service","pending",outbox.count(),"serverTime",System.currentTimeMillis());}
 @GetMapping("/queue") public Object queue(@RequestParam(defaultValue="0") int page){if(page<0)throw bad("Trang không hợp lệ");var result=outbox.findAllByOrderByAvailableAtAscIdAsc(PageRequest.of(page,20)).map(r->new Job(r.getId(),r.getUserId(),r.getAttempts(),r.getAvailableAt(),r.getExpiresAt(),r.getClaimedUntil()>System.currentTimeMillis()));return new UserOperationsController.PageView<>(result.getContent(),result.getTotalElements(),result.getNumber(),result.getTotalPages());}
 @PostMapping("/queue/{id}/retry") @Transactional public void retry(@AuthenticationPrincipal Jwt jwt,@PathVariable String id,@Valid @RequestBody Retry input){var row=outbox.lock(id).orElseThrow(()->bad("Không tìm thấy tác vụ"));if(row.getExpiresAt()<=System.currentTimeMillis()||row.getClaimedUntil()>System.currentTimeMillis())throw new ResponseStatusException(HttpStatus.CONFLICT,"Tác vụ đã hết hạn hoặc đang được xử lý");row.setAvailableAt(System.currentTimeMillis());var entry=new AdminAccountAudit();entry.setActorUserId(jwt.getSubject());entry.setTargetUserId(row.getUserId());entry.setAction("AUTH_MAIL_RETRY");entry.setNewValue("job:"+id+" / "+input.reason().trim());entry.setCreatedAt(LocalDateTime.now());audit.save(entry);}
 private static ResponseStatusException bad(String text){return new ResponseStatusException(HttpStatus.BAD_REQUEST,text);}
}
